files[0].ids[320].code.text:
{
  "code": "def update_note(note_id: str, title: Optional[str] = None,
                body: Optional[str] = None) -> Optional[Note]:
    note = _store.get(note_id)
    if note is None:
        return None
    if title is not None:
        note.title = title
    if body is not None:
        note.body = body
    note.updated_at = datetime.datetime.utcnow().isoformat(timespec="seconds") + "Z"
    return note

"
}

files[0].ids[328].code.text:
{
  "code": "def delete_note(note_id: str) -> bool:
    return _store.pop(note_id, None) is not None

"
}

files[0].ids[336].code.text:
{
  "code": "def search_notes(query: str) -> list[dict]:
    q = query.lower()
    return [n.to_dict() for n in _store.values()
            if q in n.title.lower() or q in n.body.lower()]

"
}

