    {
      "text": "def update_note(note_id: str, title: Optional[str] = None,
                body: Optional[str] = None) -> Optional[Note]:
    note = _store.get(note_id)
    if note is None:
        return None
    if title is not None:
        note.title = title
    if body is not None:
        note.body = body
    note.updated_at = datetime.datetime.utcnow().isoformat(timespec="seconds") + "Z"
    return note

",
      "file": "config.json",
      "line": 1
