  "files[2].ids[2].code": [
    {
      "text": "def create_note(title: str, body: str = "") -> Note:
    now = datetime.datetime.utcnow().isoformat(timespec="seconds") + "Z"
    note = Note(
        id=str(uuid.uuid4()),
        title=title or "Untitled",
        body=body,
        created_at=now,
        updated_at=now,
    )
    _store[note.id] = note
    return note

",
      "file": "config.json",
      "line": 1
    }
  ]
}

