    {
      "text": "function",
      "file": "config.json",
      "line": 1,
      "id": "files[2].ids[5].kind"
    },
    {
      "text": "def update_note(note_id: str, title: Optional[str] = None,\n                body: Optional[str] = None) -> Optional[Note]:\n    note = _store.get(note_id)\n    if note is None:\n        return None\n    if title is not None:\n        note.title = title\n    if body is not None:\n        note.body = body\n    note.updated_at = datetime.datetime.utcnow().isoformat(timespec=\"seconds\") + \"Z\"\n    return note\n\n",
      "file": "config.json",
      "line": 1,
      "id": "files[2].ids[5].code"
    },
