    },
    {
      "text": "def create_note(title: str, body: str = \"\") -> Note:\n    now = datetime.datetime.utcnow().isoformat(timespec=\"seconds\") + \"Z\"\n    note = Note(\n        id=str(uuid.uuid4()),\n        title=title or \"Untitled\",\n        body=body,\n        created_at=now,\n        updated_at=now,\n    )\n    _store[note.id] = note\n    return note\n\n",
      "file": "config.json",
      "line": 1,
      "id": "files[2].ids[2].code"
