      "id": "tree.get_note._meta.file"
    },
    {
      "text": "def get_note(note_id: str) -> Optional[Note]:\n    return _store.get(note_id)\n\n",
      "file": "config.json",
      "line": 1,
      "id": "tree.get_note._code"
    },
