      "text": "handler.py",
      "file": "config.json",
      "line": 1,
      "id": "tree.list_notes._meta.file"
    },
    {
      "text": "def list_notes() -> list[dict]:\n    return [n.to_dict() for n in sorted(_store.values(),\n                                         key=lambda n: n.updated_at, reverse=True)]\n\n",
      "file": "config.json",
      "line": 1,
      "id": "tree.list_notes._code"
    },
