}

{
  "text": ".notes-header { display: flex; justify-content: space-between; align-items: center; padding: 12px 0; border-bottom: 1px solid #30363d; }"
}

{
  "text": ".btn-new { background: #238636; color: #fff; border: none; padding: 8px 14px; border-radius: 6px; cursor: pointer; font-size: 13px; }"
}

{
  "text": ".notes-search input { width: 100%; background: #161b22; color: #c9d1d9; border: 1px solid #30363d; border-radius: 6px; padding: 10px; font-size: 13px; }"
}

{
  "text": ".notes-list { display: grid; grid-template-columns: repeat(auto-fill, minmax(220px, 1fr)); gap: 10px; }"
}

{
  "text": ".note-card { background: #161b22; border: 1px solid #30363d; border-radius: 8px; padding: 12px; cursor: pointer; transition: all .12s; }"
}

{
  "text": ".note-card .body { color: #8b949e; font-size: 12px; line-height: 1.5; max-height: 60px; overflow: hidden; }"
}

{
  "text": ".notes-editor { position: fixed; inset: 0; background: #0d1117; padding: 16px; z-index: 100; display: flex; flex-direction: column; }"
}

{
  "text": ".editor-bar input { flex: 1; background: #161b22; color: #e6edf3; border: 1px solid #30363d; border-radius: 6px; padding: 10px; font-size: 14px; }"
}

{
  "text": ".editor-bar button { background: #21262d; color: #c9d1d9; border: 1px solid #30363d; border-radius: 6px; padding: 8px 14px; cursor: pointer; font-size: 13px; }"
}

{
  "text": "#noteBody { flex: 1; background: #161b22; color: #e6edf3; border: 1px solid #30363d; border-radius: 6px; padding: 12px; font-size: 14px; font-family: inherit; resize: none; min-height: 300px; }"
}

