        "text": "function",
        "file": "config.json",
        "line": 1
      }
    ],
    "files[2].ids[6].code": [
      {
        "text": "def delete_note(note_id: str) -> bool:\n    return _store.pop(note_id, None) is not None\n\n",
        "file": "config.json",
        "line": 1
      }
    ],
    "files[2].ids[6].file": [
