      }
    ],
    "files[2].ids[7].code": [
      {
        "text": "def search_notes(query: str) -> list[dict]:\n    q = query.lower()\n    return [n.to_dict() for n in _store.values()\n            if q in n.title.lower() or q in n.body.lower()]\n\n",
        "file": "config.json",
        "line": 1
      }
