    },
    {
      "text": "handler.py",
      "file": "config.json",
      "line": 1,
      "id": "tree.create_note._meta.file"
    },
    {
      "text": "def create_note(title: str, body: str = \"\") -> Note:\n    now = datetime.datetime.utcnow().isoformat(timespec=\"seconds\") + \"Z\"\n    note = Note(\n        id=str(uuid.uuid4()),\n        title=title or \"Untitled\",\n        body=body,\n        created_at=now,\n        updated_at=now,\n    )\n    _store[note.id] = note\n    return note\n\n",
      "file": "config.json",
      "line": 1,
      "id": "tree.create_note._code"
    },
    {
      "text": "function",
      "file": "config.json",
      "line": 1,
      "id": "tree.get_note._meta.kind"
    },
    {
      "text": "handler.py",
      "file": "config.json",
      "line": 1,
      "id": "tree.get_note._meta.file"
    },
    {
      "text": "def get_note(note_id: str) -> Optional[Note]:\n    return _store.get(note_id)\n\n",
      "file": "config.json",
      "line": 1,
      "id": "tree.get_note._code"
    },
    {
      "text": "function",
      "file": "config.json",
      "line": 1,
      "id": "tree.list_notes._meta.kind"
    },
    {
      "text": "handler.py",
      "file": "config.json",
      "line": 1,
      "id": "tree.list_notes._meta.file"
    },
    {
      "text": "def list_notes() -> list[dict]:\n    return [n.to_dict() for n in sorted(_store.values(),\n                                         key=lambda n: n.updated_at, reverse=True)]\n\n",
      "file": "config.json",
      "line": 1,
      "id": "tree.list_notes._code"
    },
    {
      "text": "function",
      "file": "config.json",
      "line": 1,
      "id": "tree.update_note._meta.kind"
    },
    {
      "text": "handler.py",
      "file": "config.json",
      "line": 1,
      "id": "tree.update_note._meta.file"
    },
    {
      "text": "def update_note(note_id: str, title: Optional[str] = None,\n                body: Optional[str] = None) -> Optional[Note]:\n    note = _store.get(note_id)\n    if note is None:\n        return None\n    if title is not None:\n        note.title = title\n    if body is not None:\n        note.body = body\n    note.updated_at = datetime.datetime.utcnow().isoformat(timespec=\"seconds\") + \"Z\"\n    return note\n\n",
      "file": "config.json",
      "line": 1,
      "id": "tree.update_note._code"
    },
