      "text": "handler.py",
      "file": "config.json",
      "line": 1,
      "id": "tree.delete_note._meta.file"
    },
    {
      "text": "def delete_note(note_id: str) -> bool:\n    return _store.pop(note_id, None) is not None\n\n",
      "file": "config.json",
      "line": 1,
      "id": "tree.delete_note._code"
    },
